{"path": "phone_number.py", "content": "import string

_ALLOWED_PUNCTUATION = set("()+-. ")


class PhoneNumber:
    def __init__(self, number):
        self.number = self._clean(number)
        self.area_code = self.number[:3]
        self.exchange_code = self.number[3:6]
        self.subscriber_number = self.number[6:]

    def pretty(self):
        return f"({self.area_code})-{self.exchange_code}-{self.subscriber_number}"

    @staticmethod
    def _clean(number):
        stripped = "".join(ch for ch in number if ch not in _ALLOWED_PUNCTUATION)
        if any(ch.isalpha() for ch in stripped):
            raise ValueError("letters not permitted")
        if any(not ch.isdigit() for ch in stripped):
            raise ValueError("punctuations not permitted")

        digits = stripped
        if len(digits) < 10:
            raise ValueError("must not be fewer than 10 digits")
        if len(digits) > 11:
            raise ValueError("must not be greater than 11 digits")
        if len(digits) == 11:
            if digits[0] != "1":
                raise ValueError("11 digits must start with 1")
            digits = digits[1:]

        if digits[0] == "0":
            raise ValueError("area code cannot start with zero")
        if digits[0] == "1":
            raise ValueError("area code cannot start with one")
        if digits[3] == "0":
            raise ValueError("exchange code cannot start with zero")
        if digits[3] == "1":
            raise ValueError("exchange code cannot start with one")
        return digits
